[{"order":1,"type":"heading","text":"SOLID Principles in PHP: A Technical Tutorial"},{"order":2,"type":"paragraph","text":"SOLID is an acronym representing five fundamental principles of object-oriented programming and design. These principles, when applied correctly, lead to more maintainable, flexible, and robust software. This tutorial will explore each principle with PHP examples."},{"order":3,"type":"subheading","text":"1. Single Responsibility Principle (SRP)"},{"order":4,"type":"paragraph","text":"A class should have only one reason to change. In other words, a class should have only one responsibility. This principle promotes high cohesion and low coupling."},{"order":5,"type":"code","text":"// Bad example: A class with multiple responsibilities
class User {
    public function save(array $userData) {
        // Save user data to the database
    }

    public function sendEmail(string $email, string $message) {
        // Send an email to the user
    }
}

// Good example: Separating responsibilities
class User {
    public function save(array $userData) {
        // Save user data to the database
    }
}

class EmailService {
    public function sendEmail(string $email, string $message) {
        // Send an email to the user
    }
}"},{"order":6,"type":"paragraph","text":"In the 'bad' example, the 'User' class is responsible for both saving user data and sending emails. The 'good' example separates these responsibilities into two classes: 'User' and 'EmailService'. This makes the code more modular and easier to maintain."},{"order":7,"type":"subheading","text":"2. Open/Closed Principle (OCP)"},{"order":8,"type":"paragraph","text":"Software entities (classes, modules, functions, etc.) should be open for extension, but closed for modification. This means you should be able to add new functionality without modifying existing code."},{"order":9,"type":"code","text":"// Bad example: Modifying existing code to add new functionality
class Order {
    public function calculateTotal(array $items, string $paymentType) {
        $total = 0;
        foreach ($items as $item) {
            $total += $item['price'] * $item['quantity'];
        }

        if ($paymentType === 'paypal') {
            // Apply PayPal discount
            $total *= 0.9;
        } elseif ($paymentType === 'credit_card') {
            // Apply credit card surcharge
            $total *= 1.05;
        }

        return $total;
    }
}

// Good example: Using inheritance and interfaces
interface PaymentProcessor {
    public function calculateTotal(float $total): float;
}

class PaypalProcessor implements PaymentProcessor {
    public function calculateTotal(float $total): float {
        return $total * 0.9;
    }
}

class CreditCardProcessor implements PaymentProcessor {
    public function calculateTotal(float $total): float {
        return $total * 1.05;
    }
}

class Order {
    public function calculateTotal(array $items, PaymentProcessor $paymentProcessor): float {
        $total = 0;
        foreach ($items as $item) {
            $total += $item['price'] * $item['quantity'];
        }

        return $paymentProcessor->calculateTotal($total);
    }
}"},{"order":10,"type":"paragraph","text":"In the 'bad' example, adding a new payment type requires modifying the 'calculateTotal' method. The 'good' example uses an interface 'PaymentProcessor' and concrete classes for each payment type. This allows adding new payment types without modifying the 'Order' class."},{"order":11,"type":"subheading","text":"3. Liskov Substitution Principle (LSP)"},{"order":12,"type":"paragraph","text":"Subtypes must be substitutable for their base types without altering the correctness of the program. In simpler terms, if you have a class 'A' and a class 'B' that inherits from 'A', you should be able to use 'B' anywhere 'A' is used without causing unexpected behavior."},{"order":13,"type":"code","text":"// Bad example: Violating LSP
class Rectangle {
    protected $width;
    protected $height;

    public function setWidth(int $width) {
        $this->width = $width;
    }

    public function setHeight(int $height) {
        $this->height = $height;
    }

    public function getArea(): int {
        return $this->width * $this->height;
    }
}

class Square extends Rectangle {
    public function setWidth(int $width) {
        $this->width = $width;
        $this->height = $width;
    }

    public function setHeight(int $height) {
        $this->width = $height;
        $this->height = $height;
    }
}

function calculateArea(Rectangle $rectangle) {
    $rectangle->setWidth(5);
    $rectangle->setHeight(4);

    return $rectangle->getArea();
}

// This will work fine for Rectangle
$rectangle = new Rectangle();
echo 'Rectangle Area: ' . calculateArea($rectangle) . "\n"; // Output: Rectangle Area: 20

// But it will produce unexpected results for Square
$square = new Square();
echo 'Square Area: ' . calculateArea($square) . "\n"; // Output: Square Area: 16 (incorrect)

// Good example: Adhering to LSP
interface Shape {
    public function getArea(): int;
}

class Rectangle implements Shape {
    private $width;
    private $height;

    public function __construct(int $width, int $height) {
        $this->width = $width;
        $this->height = $height;
    }

    public function getArea(): int {
        return $this->width * $this->height;
    }
}

class Square implements Shape {
    private $side;

    public function __construct(int $side) {
        $this->side = $side;
    }

    public function getArea(): int {
        return $this->side * $this->side;
    }
}

function calculateArea(Shape $shape) {
    return $shape->getArea();
}

$rectangle = new Rectangle(5, 4);
echo 'Rectangle Area: ' . calculateArea($rectangle) . "\n"; // Output: Rectangle Area: 20

$square = new Square(4);
echo 'Square Area: ' . calculateArea($square) . "\n"; // Output: Square Area: 16"},{"order":14,"type":"paragraph","text":"In the 'bad' example, the 'Square' class violates LSP because setting the width or height of a 'Square' also changes the other dimension, leading to unexpected results when used in a context expecting a 'Rectangle'. The 'good' example uses an interface 'Shape' and separate classes for 'Rectangle' and 'Square', ensuring that each class behaves as expected."},{"order":15,"type":"subheading","text":"4. Interface Segregation Principle (ISP)"},{"order":16,"type":"paragraph","text":"Clients should not be forced to depend on methods they do not use. This means that large interfaces should be split into smaller, more specific interfaces, so that clients only need to know about the methods that are of interest to them."},{"order":17,"type":"code","text":"// Bad example: A large interface
interface Worker {
    public function work(): void;
    public function eat(): void;
    public function sleep(): void;
}

class HumanWorker implements Worker {
    public function work(): void { /* ... */ }
    public function eat(): void { /* ... */ }
    public function sleep(): void { /* ... */ }
}

class RobotWorker implements Worker {
    public function work(): void { /* ... */ }
    public function eat(): void { /* This robot doesn't eat, but must implement the method */ }
    public function sleep(): void { /* This robot doesn't sleep, but must implement the method */ }
}

// Good example: Segregated interfaces
interface Workable {
    public function work(): void;
}

interface Eatable {
    public function eat(): void;
}

interface Sleepable {
    public function sleep(): void;
}

class HumanWorker implements Workable, Eatable, Sleepable {
    public function work(): void { /* ... */ }
    public function eat(): void { /* ... */ }
    public function sleep(): void { /* ... */ }
}

class RobotWorker implements Workable {
    public function work(): void { /* ... */ }
}"},{"order":18,"type":"paragraph","text":"In the 'bad' example, the 'RobotWorker' class is forced to implement the 'eat' and 'sleep' methods, even though robots don't eat or sleep. The 'good' example segregates the 'Worker' interface into smaller interfaces: 'Workable', 'Eatable', and 'Sleepable'. This allows the 'RobotWorker' class to only implement the 'Workable' interface."},{"order":19,"type":"subheading","text":"5. Dependency Inversion Principle (DIP)"},{"order":20,"type":"paragraph","text":"High-level modules should not depend on low-level modules. Both should depend on abstractions. Abstractions should not depend on details. Details should depend on abstractions. This principle promotes loose coupling and makes the code more testable and reusable."},{"order":21,"type":"code","text":"// Bad example: High-level module depending on a low-level module
class LightBulb {
    public function turnOn(): void {
        // Turn on the light bulb
    }

    public function turnOff(): void {
        // Turn off the light bulb
    }
}

class Switch {
    private $lightBulb;

    public function __construct(LightBulb $lightBulb) {
        $this->lightBulb = $lightBulb;
    }

    public function operate(): void {
        $this->lightBulb->turnOn();
    }
}

// Good example: High-level module depending on an abstraction
interface Switchable {
    public function turnOn(): void;
    public function turnOff(): void;
}

class LightBulb implements Switchable {
    public function turnOn(): void {
        // Turn on the light bulb
    }

    public function turnOff(): void {
        // Turn off the light bulb
    }
}

class Switch {
    private $device;

    public function __construct(Switchable $device) {
        $this->device = $device;
    }

    public function operate(): void {
        $this->device->turnOn();
    }
}"},{"order":22,"type":"paragraph","text":"In the 'bad' example, the 'Switch' class depends directly on the 'LightBulb' class. This makes the 'Switch' class tightly coupled to the 'LightBulb' class. The 'good' example uses an interface 'Switchable' to abstract the dependency. Now, the 'Switch' class depends on the 'Switchable' interface, and the 'LightBulb' class implements the 'Switchable' interface. This makes the code more flexible and allows the 'Switch' to control any device that implements the 'Switchable' interface."},{"order":23,"type":"paragraph","text":"By adhering to the SOLID principles, you can create PHP applications that are easier to understand, maintain, and extend. These principles promote good design practices and help you avoid common pitfalls in object-oriented programming."}]
